const fs=require('fs'),ts=require('typescript'),assert=require('assert/strict'),path=require('path');const cache={};function load(file){file=path.resolve(file);if(cache[file])return cache[file].exports;const m={exports:{}};cache[file]=m;new Function('require','module','exports',ts.transpileModule(fs.readFileSync(file,'utf8'),{compilerOptions:{module:1,target:9,esModuleInterop:true}}).outputText)(n=>n.startsWith('@/')?load('src/'+n.slice(2)+'.ts'):n.startsWith('.')?load(path.resolve(path.dirname(file),n)+'.ts'):require(n),m,m.exports);return m.exports;}
const signup=load('src/lib/auth/signup-fields.ts').parseSignupForm,purchase=load('src/lib/store/purchase-profile.ts').parsePurchaseProfile;function form(values){const f=new FormData();Object.entries(values).forEach(([k,v])=>f.set(k,v));return f;}
const valid={account_type:'business',company_name:'Hanmi Trade',country_code:'KR',email:'buyer@example.com',full_name:'Jane Buyer',password:'secure12345',password_confirm:'secure12345',preferred_currency:'USD',accept_terms:'on',accept_privacy:'on',phone_country:'KR',phone_number:'01012345678'};
assert.equal(signup(form(valid)).accountType,'business');assert.equal(signup(form({...valid,company_name:''})).errorKey,'companyRequired');for(const type of ['', 'personal', 'admin'])assert.equal(signup(form({...valid,account_type:type})).errorKey,'accountTypeRequired');
assert.equal(purchase(form({})).errorKey,'purposeRequired');assert.equal(purchase(form({purchase_purpose:'retail'})).errorKey,'channelRequired');const resale={purchase_purpose:'retail',sales_channel:'amazon',sales_country:'US',sales_details:'Example store https://www.amazon.com/stores/example'};assert.equal(purchase(form(resale)).salesCountry,'US');assert.equal(purchase(form({...resale,sales_country:'XX'})).errorKey,'countryRequired');assert.equal(purchase(form({...resale,sales_details:''})).errorKey,'detailsRequired');assert.equal(purchase(form({...resale,sales_details:'<script>'})).errorKey,'invalidDetails');assert.equal(purchase(form({...resale,sales_details:'x'.repeat(501)})).errorKey,'invalidDetails');assert.equal(purchase(form({...resale,purchase_purpose:'other'})).errorKey,'detailsRequired');assert.equal(purchase(form({...resale,purchase_purpose:'personal'})).errorKey,'purposeRequired');assert.equal(purchase(form({purchase_purpose:'samples'})).errorKey,'channelRequired');assert.equal(purchase(form({...resale,purchase_purpose:'samples'})).salesChannel,'amazon');assert.equal(purchase(form({...resale,sales_details:'https://www.amazon.com/'})).errorKey,'storeUrlRequired');assert.equal(purchase(form({...resale,sales_details:'Amazon'})).errorKey,'storeUrlRequired');assert.equal(purchase(form({...resale,sales_channel:'online',sales_details:'https://store.example.com/'})).salesChannel,'online');assert.equal(purchase(form({...resale,sales_channel:'other',sales_details:'Local distribution: Hanmi Store, 123 Main Street',purchase_purpose:'other',purpose_other:'Business resale'})).salesChannel,'other');
const readSaved=load('src/lib/store/purchase-profile.ts').readSavedPurchaseProfile;assert.deepEqual(readSaved(purchase(form(resale))),purchase(form(resale)));for(const value of [null, [], 'bad', {purchasePurpose:'personal'}, {...purchase(form(resale)),salesCountry:'invalid'}])assert.equal(readSaved(value),undefined);
const flatten=(obj,p='')=>Object.entries(obj).flatMap(([k,v])=>typeof v==='object'?flatten(v,p+k+'.'):[p+k]);const keys=flatten(JSON.parse(fs.readFileSync('messages/en.json')).buyerProfile).sort();for(const locale of ['en','ko','ja','zh','vi','id','th','ru','kk','uz','ky','tg','tk'])assert.deepEqual(flatten(JSON.parse(fs.readFileSync('messages/'+locale+'.json')).buyerProfile).sort(),keys);
console.log('PASS business-only signup; all purposes including samples require sales destination; Other supported; online store URL required; saved profile revalidated; all 13 locale keys. No live writes.');
